INSERT INTO sources (source_id, source_type, title, scope) VALUES
 ('SRC_MICHAELIS_ADMIRABLE','primary text','Sebastien Michaelis, The Admirable History of the Possession and Conversion of a Penitent Woman (Histoire admirable de la possession et conversion d''une penitente, Aix-en-Provence, 1612; Eng. tr. 1613) — incl. the ''Pneumalogie'' demon-hierarchy','Christian demonology'),
 ('SRC_DEPLANCY_INFERNAL','secondary scholarship','J. A. S. Collin de Plancy, Dictionnaire Infernal (1818; 6th ed. 1863)','Christian demonology')
INSERT INTO _e VALUES
 ('ENT_DEMX_LOUDUN','The Possession Demons of Aix / Loudun (Michaelis hierarchy)','Demonic collective','Adversarial collective','Christian demonology','demonic possession; exorcism','B','Collective hub for the named possessing/expelled spirits enumerated in Sebastien Michaelis'' Admirable History (Aix-en-Provence exorcisms of Madeleine de Demandolx, 1610-11), whose ''Pneumalogie'' ranks the demons of the three angelic hierarchies. Attested only within this exorcism-treatise tradition.'),
 ('ENT_DEMX_VERRINE','Verrine','Possessing spirit','Demon','Christian demonology','impatience','C','Demon of impatience named in Michaelis'' Admirable History (1612) as a possessor at Aix; ranked among the second hierarchy, with St. Dominic given as his adversary saint. Attested essentially only in Michaelis.'),
 ('ENT_DEMX_GRESIL','Gresil','Possessing spirit','Demon','Christian demonology','impurity; uncleanness','C','Demon of impurity/uncleanness in Michaelis'' Admirable History (1612), of the second hierarchy (Thrones), opposed by St. Bernard. Attested essentially only in Michaelis.'),
 ('ENT_DEMX_SONNEILLON','Sonneillon','Possessing spirit','Demon','Christian demonology','hatred','C','Demon of hatred in Michaelis'' Admirable History (1612), of the second hierarchy, whose opposing saint is St. Stephen. Attested essentially only in Michaelis.'),
 ('ENT_DEMX_CARREAU','Carreau','Possessing spirit','Demon','Christian demonology','hardness of heart; mercilessness','C','Demon of mercilessness/hardness of heart in Michaelis'' Admirable History (1612), of the first hierarchy (Powers), opposed by St. Vincent. Attested essentially only in Michaelis.'),
 ('ENT_DEMX_CARNIVEAN','Carnivean','Possessing spirit','Demon','Christian demonology','obscenity; shamelessness','C','Demon of obscenity/shamelessness in Michaelis'' Admirable History (1612), of the first hierarchy (Powers), opposed by St. John the Evangelist. Attested essentially only in Michaelis.'),
 ('ENT_DEMX_OEILLET','Oeillet','Possessing spirit','Demon','Christian demonology','breaking the vow of poverty; cupidity','C','Demon who tempts against the vow of poverty (riches/cupidity) in Michaelis'' Admirable History (1612), of the third hierarchy (Dominions), opposed by St. Martin. Attested essentially only in Michaelis.'),
 ('ENT_DEMX_ROSIER','Rosier','Possessing spirit','Demon','Christian demonology','carnal love; seduction','C','Demon of carnal love/seduction in Michaelis'' Admirable History (1612), of the third hierarchy (Dominions), opposed by St. Basil. Attested essentially only in Michaelis.'),
 ('ENT_DEMX_BAALBERITH','Baalberith','Infernal officer','Infernal officer','Christian demonology','infernal secretary/archivist; blasphemy; covenants','C','In Michaelis'' Admirable History (1612) the demon of blasphemy/quarrels, of the second hierarchy (Cherubim), opposed by St. Barnabas; later catalogues (de Plancy) make him the secretary/keeper of the archives of Hell. Derived from the biblical Baal-berith of Judges 8-9. HOMONYM: distinct from the existing Goetic spirit ENT_GOE_BERITH (Berith/Bolfry of the Ars Goetia), with which the name overlaps.'),
 ('ENT_DEMX_TITIVILLUS','Titivillus','Demon','Demon','Christian demonology','scribal errors; idle/garbled words in prayer; the sack of dropped syllables','B','The medieval-to-early-modern patron demon of scribes'' errors who collects mangled and skipped words from copyists and careless reciters of the Divine Office into a sack to be read against them at Judgment; attested from John of Wales / the Tractatus de Penitentia and later sermon and exemplum literature, surviving into early-modern demonology compendia.'),
 ('ENT_DEMX_WITCH_FAMILIAR','The Witch''s Familiar (familiar spirit)','Demon class','Demonological classification','Christian demonology','witchcraft; demonic pact; animal-shaped attendant spirits (imps)','B','Class hub for the low demonic attendant spirits (''imps''/familiars) in animal form (cat, toad, dog, etc.) said in early-modern English and continental witch-trial demonology (e.g. the Essex trials, Matthew Hopkins'' Discovery of Witches, 1647) to be given by the Devil to suckle on the witch''s mark and do her bidding. A class, not a single named being.');
